{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C06", "C51", "C46", "C53", "C43", "C08", "C12", "C09", "C01", "C11", "C17"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C06", "C51", "C46", "C53", "C43", "C08", "C12", "C09", "C01", "C11", "C17"],
  "claims": [
    {
      "claim": "Codeine, a morphinan opioid closely related to hydromorphone, had 80.5% absolute oral bioavailability in healthy subjects after oral and IV administration, directly supporting F ≥ 20% for the scaffold.",
      "card_ids": ["C06"]
    },
    {
      "claim": "L4 records show codeine is >90% absorbed (Fa 95%) and dextromethorphan, another morphinan, is completely absorbed after oral administration, supporting high intestinal absorption for the morphinan class.",
      "card_ids": ["C51", "C46", "C53", "C43"]
    },
    {
      "claim": "Pentazocine, a benzomorphan opioid with phenol and tertiary amine groups, showed mean systemic availability of 0.68–0.70 in cirrhotic patients, above the threshold.",
      "card_ids": ["C08", "C12"]
    },
    {
      "claim": "Meptazinol, a phenol-containing analgesic, had absolute bioavailability of 27.9% in cirrhotic patients, above the threshold, though disease-state first-pass reduction limits transferability.",
      "card_ids": ["C09"]
    },
    {
      "claim": "Melperone, a basic lipophilic drug, had absolute bioavailability of 54–67% in fasted healthy volunteers, supporting that basic amines with similar properties can exceed 20%.",
      "card_ids": ["C01", "C11", "C17"]
    },
    {
      "claim": "No supplied record reports F < 20% for the relevant analogues; the lowest supplied values remain above the threshold.",
      "card_ids": ["C07", "C09"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C51", "C46", "C53", "C43"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute bioavailability record is present; prediction relies on close structural analogues and absorption evidence.",
    "L4 records measure fraction absorbed, not systemic F; first-pass metabolism and systemic clearance for hydromorphone are not directly quantified.",
    "Some high-F records (pentazocine, meptazinol) are from cirrhotic patients, where first-pass metabolism is reduced; transferability to healthy/typical conditions is limited.",
    "Low neutral fraction (0.1) and possible phenol/amine metabolism are not directly resolved by the supplied records."
  ],
  "decision_summary": "L4 adds intestinal absorption evidence showing codeine Fa 95%/>90% and dextromethorphan complete absorption, supporting high absorption for the morphinan scaffold. Combined with L1 codeine absolute F 80.5% and other opioid/analgesic F values above 20%, the prediction remains high and is strengthened; no record supports F < 20%."
}

